<?php require __DIR__.'/includes/header.php';$u=require_login();$st=db()->prepare('SELECT a.*,p.name pet_name,p.image,s.name shelter_name FROM adoption_applications a JOIN pets p ON p.id=a.pet_id JOIN shelters s ON s.id=p.shelter_id WHERE a.applicant_id=? ORDER BY a.created_at DESC');$st->execute([$u['id']]);$apps=$st->fetchAll();?>
<div class="section-head"><h1>Application tracker</h1><a class="btn btn-small" href="<?=e(base_url('pets.php'))?>">Find another pet</a></div><?php if(!$apps):?><div class="panel empty">You have not submitted an adoption application yet.</div><?php else:?><div class="grid"><?php foreach($apps as $a):?><article class="card"><img class="card-image" src="<?=e(image_url($a['image']))?>" alt="<?=e($a['pet_name'])?>"><div class="card-body"><h3><?=e($a['pet_name'])?></h3><p class="muted"><?=e($a['shelter_name'])?></p><span class="badge <?=e($a['status'])?>"><?=e(str_replace('_',' ',$a['status']))?></span><p class="small">Submitted <?=e(date('M j, Y',strtotime($a['created_at'])))?></p><?php if($a['shelter_notes']):?><div class="notice small"><?=e($a['shelter_notes'])?></div><?php endif;?></div></article><?php endforeach;?></div><?php endif;?>
<?php require __DIR__.'/includes/footer.php'; ?>
